CREATE TEMPORARY VIEW user_exp_mapping_${grass_region_without_quote} AS
SELECT
    user_id
    ,exp_group_id
FROM
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND is_assignment_log = 1
    AND is_search_whitelist = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_fp_search_${grass_region_without_quote} AS
SELECT
    user_id
    ,item_id
    ,request_id
    ,if(is_ads is null, false, is_ads) as is_ads
    ,true AS is_login
    ,sort_type
    ,MAX(rel_raw) AS rel_raw
    ,MAX(rel_lx) AS rel_lx
    ,MAX(rel_add) AS rel_add
FROM srdi_mart.dwd_fp_search_base_1d
WHERE country IN (${grass_region})
      AND dt = ${local_date}
      AND location <= 39
      AND imp_time IS NOT NULL
      AND user_id > 0
GROUP BY  
    1,2,3,4,5,6;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_rel_metrics_by_req_${grass_region_without_quote} AS
SELECT 
      user_id
      ,request_id
      ,if(is_ads IS NOT NULL, cast(is_ads AS STRING), '__ALL__') AS is_ads
      ,true AS is_login
      ,sort_type
      ,sum(CASE WHEN rel_raw >=0 THEN rel_raw ELSE 0 END)/count(1) AS rel_avg_score
      ,sum(CASE WHEN rel_lx >=0 THEN rel_lx ELSE 0 END)/count(1) AS rel_avg_lx
      ,sum(CASE WHEN rel_add >=0 THEN rel_add ELSE 0 END)/count(1) AS rel_avg_add
      ,sum(CASE WHEN rel_lx = 0 THEN 1 ELSE 0 END)/count(1) AS irrelevance_rate
FROM dwd_fp_search_${grass_region_without_quote}
      GROUP BY GROUPING SETS
(
    (user_id, is_ads, is_login, sort_type, request_id), (user_id, is_login, sort_type, request_id)
);

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_rel_metrics_by_user_${grass_region_without_quote} AS
SELECT 
      user_id
      ,is_ads
      ,is_login
      ,sort_type
      ,sum(rel_avg_score) AS total_rel_avg_score
      ,sum(rel_avg_lx) AS total_rel_avg_lx
      ,sum(rel_avg_add) AS total_rel_avg_add
      ,sum(irrelevance_rate) AS total_irrelevance_rate
      ,count(request_id) AS num_requests
FROM 
      search_rel_metrics_by_req_${grass_region_without_quote}
GROUP BY 1,2,3,4;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_relevance_metrics_1d
PARTITION (
    grass_region=${grass_region},
    local_date=${local_date}
)
SELECT 
      exp_group_id
      ,is_login
      ,sort_type
      ,sum(total_rel_avg_score) AS total_rel_avg_score
      ,sum(total_rel_avg_lx) AS total_rel_avg_lx
      ,sum(total_rel_avg_add) AS total_rel_avg_add
      ,sum(total_irrelevance_rate) AS total_irrelevance_rate
      ,sum(num_requests) AS num_requests
      ,is_ads
FROM 
      search_rel_metrics_by_user_${grass_region_without_quote} a
      INNER JOIN user_exp_mapping_${grass_region_without_quote} b
            ON a.user_id = b.user_id
GROUP BY
      exp_group_id, is_login, sort_type, is_ads
